import{_ as a,o as e,c as r,a4 as l}from"./chunks/framework.BybBnFXO.js";const p=JSON.parse('{"title":"传奇宝石","description":"","frontmatter":{"title":"传奇宝石","gallery":"legendary-stones"},"headers":[],"relativePath":"zh/gallery/legendary-stones.md","filePath":"zh/gallery/legendary-stones.md","lastUpdated":1785925441000}'),o={name:"zh/gallery/legendary-stones.md"};function d(n,t,i,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="传奇宝石" tabindex="-1">传奇宝石 <a class="header-anchor" href="#传奇宝石" aria-label="Permalink to &quot;传奇宝石&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>少数宝石因尺寸、颜色或历史而名垂青史——Hope 蓝钻、Koh-i-Noor、 Cullinan 系列、Regent 钻石、Star of India。它们的故事与它们本身一样珍贵。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>Hope 蓝钻 (45.52 ct)：世界最著名蓝钻，切磨自法国王室蓝钻，现藏史密森尼。</li><li>Koh-i-Noor (105.6 ct)：莫卧儿&quot;光之山&quot;，现为英国王冠上石。</li><li>Cullinan I (530.2 ct)：最大顶级切割钻石，&quot;非洲之星&quot;，镶嵌英王权杖。</li><li>Regent 钻石 (140.6 ct)：曾镶路易十五王冠，现存卢浮宫。</li><li>Star of India (563 ct)：世界最大星光蓝宝石，现藏美国自然史博物馆。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作品</th><th>详情</th><th>备注</th></tr></thead><tbody><tr><td>Hope Diamond</td><td>45.52 ct, blue</td><td>—</td></tr><tr><td>Cullinan I</td><td>530.2 ct, D colour</td><td>—</td></tr><tr><td>Star of India</td><td>563 ct, star sapphire</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const _=a(o,[["render",d]]);export{p as __pageData,_ as default};
